    "BOB",
    {"ALICE"},
    {"ALICE": ["I am guilty."], "BOB": ["ALICE is guilty."], "CHARLIE": []},
    {"MONDAY"}
) == False  # Alice lies by saying guilty, but we assumed she is liar

assert check_scenario(
    "CHARLIE",
    set(),
    {"ALICE": ["ALICE is not guilty."], "BOB": ["CHARLIE is guilty."], "CHARLIE": ["I am guilty."]},
    {"MONDAY", "TUESDAY"}
) == False  # Charlie is not liar, but claims guilty while not matched

assert check_scenario(
    "DAVE",
    {"EVE"},
    {"ALICE": ["ALICE is guilty."], "BOB": ["DAVE is not guilty."], "EVE": ["DAVE is guilty."]},
    {"MONDAY", "TUESDAY"}
) == True
